function validate([s, k]) {
  if (s.length < 3 || s.length > 30000) return 's needs 3 to 3 * 10^4 characters.';
  if (!/^[0-4]+$/.test(s)) return 's may contain only the digits 0 to 4.';
  if (k < 1 || k > s.length) return 'k is between 1 and the length of s.';
  // Some substring of length >= k must have one digit an odd number of times and another an even, nonzero number of times.
  for (let a = 0; a < 5; a++) for (let b = 0; b < 5; b++) {
    if (a === b) continue;
    const seen = [false, false, false, false];
    let left = 0, leftA = 0, leftB = 0, countA = 0, countB = 0;
    for (let right = 0; right < s.length; right++) {
      if (+s[right] === a) countA++;
      if (+s[right] === b) countB++;
      while (right + 1 - left >= k && countB - leftB >= 2) { seen[(leftA % 2) * 2 + leftB % 2] = true; if (+s[left] === a) leftA++; if (+s[left] === b) leftB++; left++; }
      if (seen[(1 - countA % 2) * 2 + countB % 2]) return null;
    }
  }
  return 'No substring of length at least k has one digit an odd number of times and another an even, nonzero number of times.';
}

