function maxDifference(s, k) {
  let answer = -Infinity;
  for (let a = 0; a < 5; a++) {
    for (let b = 0; b < 5; b++) {
      if (a === b) continue;
      const minDiff = [[Infinity, Infinity], [Infinity, Infinity]];
      let countA = 0, countB = 0;
      let left = 0, leftA = 0, leftB = 0;
      for (let right = 0; right < s.length; right++) {
        const digit = Number(s[right]);
        if (digit === a) countA++;
        if (digit === b) countB++;
        while (right + 1 - left >= k && countB - leftB >= 2) {
          const p = leftA % 2;
          const q = leftB % 2;
          minDiff[p][q] = Math.min(minDiff[p][q], leftA - leftB);
          if (Number(s[left]) === a) leftA++;
          if (Number(s[left]) === b) leftB++;
          left++;
        }
        const prior = minDiff[1 - countA % 2][countB % 2];
        if (prior !== Infinity) {
          answer = Math.max(answer, countA - countB - prior);
        }
      }
    }
  }
  return answer;
}

