function maxDifference(s, k) {
  // Count the digits of every substring of length at least k and try every odd count against every nonzero even count.
  let best = -Infinity;
  for (let start = 0; start < s.length; start++) {
    const freq = [0, 0, 0, 0, 0];
    for (let end = start; end < s.length; end++) {
      freq[Number(s[end])]++;
      if (end - start + 1 < k) continue;
      for (const odd of freq) {
        if (odd % 2 === 0) continue;
        for (const even of freq) if (even > 0 && even % 2 === 0) best = Math.max(best, odd - even);
      }
    }
  }
  return best;
}

