function generate(rand, size) {
  const large = size === 'large';
  // Whether some substring of length >= k has a digit with an odd count and another with a nonzero even count.
  const valid = (s, k) => {
    for (let a = 0; a < 5; a++) for (let b = 0; b < 5; b++) {
      if (a === b) continue;
      const seen = [false, false, false, false];
      let left = 0, leftA = 0, leftB = 0, countA = 0, countB = 0;
      for (let right = 0; right < s.length; right++) {
        if (+s[right] === a) countA++;
        if (+s[right] === b) countB++;
        while (right + 1 - left >= k && countB - leftB >= 2) { seen[(leftA % 2) * 2 + leftB % 2] = true; if (+s[left] === a) leftA++; if (+s[left] === b) leftB++; left++; }
        if (seen[(1 - countA % 2) * 2 + countB % 2]) return true;
      }
    }
    return false;
  };
  for (;;) {
    const n = large ? 8000 + Math.floor(rand() * 2001) : 3 + Math.floor(rand() * 12);
    // A few digits with uneven weights, so that long runs and lopsided counts appear.
    const used = 2 + Math.floor(rand() * 4), offset = Math.floor(rand() * 5);
    const weights = Array.from({ length: used }, () => 0.05 + rand());
    const total = weights.reduce((x, y) => x + y, 0);
    let s = '';
    for (let i = 0; i < n; i++) {
      let pick = rand() * total, j = 0;
      while (j < used - 1 && pick >= weights[j]) pick -= weights[j++];
      s += String((offset + j) % 5);
    }
    const roll = rand();
    const k = roll < 0.3 ? 1 + Math.floor(rand() * 3) : roll < 0.6 ? Math.max(1, n - Math.floor(rand() * (large ? 50 : 3))) : 1 + Math.floor(rand() * n);
    if (valid(s, k)) return [s, k];
  }
}
